-- A fresh external epoch/digest is required for controlled recovery; no production approval is seeded.
CREATE TABLE recovery_replay_runs(id UUID PRIMARY KEY DEFAULT uuidv7(),epoch UUID NOT NULL UNIQUE,source_commit CHAR(40) NOT NULL,manifest_sha256 CHAR(64) NOT NULL,prepared_by UUID NOT NULL REFERENCES users(id),prepared_session UUID NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recovery_replay_subjects(run_id UUID NOT NULL REFERENCES recovery_replay_runs(id),subject_id UUID NOT NULL REFERENCES users(id),domain TEXT NOT NULL CHECK(domain IN('ALL','SOCIAL','WELLBEING','LISTENER','CLINIC','FINANCE')),PRIMARY KEY(run_id,subject_id,domain));
CREATE TABLE recovery_replay_stops(run_id UUID NOT NULL REFERENCES recovery_replay_runs(id),service TEXT NOT NULL CHECK(service IN('SOCIAL','WELLBEING','LISTENER','CLINIC','FINANCE')),PRIMARY KEY(run_id,service));
CREATE TABLE recovery_replay_reviews(run_id UUID PRIMARY KEY REFERENCES recovery_replay_runs(id),reviewer_id UUID NOT NULL REFERENCES users(id),review_session UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recovery_replay_revocations(run_id UUID PRIMARY KEY REFERENCES recovery_replay_runs(id),subject_id UUID REFERENCES users(id),reason TEXT NOT NULL CHECK(reason IN('AUTHORITY_REMOVED','ACCOUNT_RESTRICTED','EXPLICIT_STOP')),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX recovery_replay_subject_access ON recovery_replay_subjects(subject_id,domain);
CREATE FUNCTION invalidate_recovery_authority() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO recovery_replay_revocations(run_id,subject_id,reason) SELECT r.id,OLD.user_id,'AUTHORITY_REMOVED' FROM recovery_replay_runs r LEFT JOIN recovery_replay_reviews v ON v.run_id=r.id WHERE (r.prepared_by=OLD.user_id OR v.reviewer_id=OLD.user_id) AND OLD.role_id IN(SELECT id FROM roles WHERE name='TRUST_ACCOUNT') ON CONFLICT DO NOTHING;RETURN OLD;END $$;
CREATE TRIGGER recovery_role_revocation AFTER DELETE ON user_roles FOR EACH ROW EXECUTE FUNCTION invalidate_recovery_authority();
CREATE FUNCTION invalidate_recovery_account() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN IF NEW.status<>'ACTIVE' OR NOT NEW.email_verified THEN INSERT INTO recovery_replay_revocations(run_id,subject_id,reason) SELECT r.id,NEW.id,'ACCOUNT_RESTRICTED' FROM recovery_replay_runs r LEFT JOIN recovery_replay_reviews v ON v.run_id=r.id WHERE r.prepared_by=NEW.id OR v.reviewer_id=NEW.id ON CONFLICT DO NOTHING;END IF;RETURN NEW;END $$;
CREATE TRIGGER recovery_account_restriction AFTER UPDATE OF status,email_verified ON users FOR EACH ROW EXECUTE FUNCTION invalidate_recovery_account();
DO $$ DECLARE tab TEXT;BEGIN FOREACH tab IN ARRAY ARRAY['recovery_replay_runs','recovery_replay_subjects','recovery_replay_stops','recovery_replay_reviews','recovery_replay_revocations'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION clinic_append_only()',tab||'_immutable',tab);END LOOP;END $$;
